begin;
create schema if not exists tm_private;
revoke all on schema tm_private from public;
grant usage on schema tm_private to authenticated;
create table public.tm_projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),name text not null check(length(name) between 1 and 200),course text not null default '',deadline date,invite_code text not null unique default encode(gen_random_bytes(16),'hex'),created_at timestamptz not null default now());
create table public.tm_members(project_id uuid references public.tm_projects(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,name text not null,role text not null default '팀원',primary key(project_id,user_id));
create index tm_members_user on public.tm_members(user_id);
create table public.tm_items(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.tm_projects(id) on delete cascade,kind text not null check(kind in ('task','resource','slide','feedback')),title text not null check(length(title) between 1 and 300),body text default '',topic text default '',owner uuid references auth.users(id),status text default 'todo' check(status in ('todo','doing','done')),due date,author uuid not null references auth.users(id),url text default '',highlight text default '',file_path text,script text default '',resource_ids uuid[] default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index tm_items_project on public.tm_items(project_id);
create index tm_items_author on public.tm_items(author);
create index tm_items_owner on public.tm_items(owner);
alter table public.tm_projects enable row level security;
alter table public.tm_members enable row level security;
alter table public.tm_items enable row level security;
create function tm_private.is_member(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.tm_members where project_id=pid and user_id=auth.uid())$$;
create function tm_private.is_owner(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.tm_projects where id=pid and owner_id=auth.uid())$$;
revoke all on function tm_private.is_member(uuid),tm_private.is_owner(uuid) from public;
grant execute on function tm_private.is_member(uuid),tm_private.is_owner(uuid) to authenticated;
create policy project_read on public.tm_projects for select to authenticated using(tm_private.is_member(id));
create policy member_read on public.tm_members for select to authenticated using(tm_private.is_member(project_id));
create policy member_edit on public.tm_members for update to authenticated using(user_id=(select auth.uid()) or tm_private.is_owner(project_id)) with check(user_id=(select auth.uid()) or tm_private.is_owner(project_id));
create policy item_read on public.tm_items for select to authenticated using(tm_private.is_member(project_id));
create policy item_insert on public.tm_items for insert to authenticated with check(tm_private.is_member(project_id) and author=(select auth.uid()) and (owner is null or exists(select 1 from public.tm_members m where m.project_id=tm_items.project_id and m.user_id=tm_items.owner)));
create policy item_edit on public.tm_items for update to authenticated using(tm_private.is_member(project_id)) with check(tm_private.is_member(project_id) and (owner is null or exists(select 1 from public.tm_members m where m.project_id=tm_items.project_id and m.user_id=tm_items.owner)));
create function tm_private.guard_item() returns trigger language plpgsql set search_path='' as $$begin if new.project_id<>old.project_id or new.author<>old.author or new.id<>old.id or new.created_at<>old.created_at then raise exception 'Cannot change item ownership';end if;new.updated_at=clock_timestamp();return new;end$$;
create trigger guard_item before update on public.tm_items for each row execute function tm_private.guard_item();
create function tm_private.create_project(project_name text,course_name text,due_date date,display_name text) returns uuid language plpgsql security definer set search_path='' as $$declare pid uuid;begin if auth.uid() is null then raise exception 'Login required';end if;insert into public.tm_projects(owner_id,name,course,deadline) values(auth.uid(),project_name,course_name,due_date) returning id into pid;insert into public.tm_members values(pid,auth.uid(),left(coalesce(nullif(display_name,''),'팀원'),50),'팀장');return pid;end$$;
create function tm_private.join_project(code text,display_name text) returns uuid language plpgsql security definer set search_path='' as $$declare pid uuid;begin if auth.uid() is null then raise exception 'Login required';end if;select id into pid from public.tm_projects where invite_code=code;if pid is null then raise exception '초대 코드를 확인해주세요.';end if;insert into public.tm_members(project_id,user_id,name) values(pid,auth.uid(),left(coalesce(nullif(display_name,''),'팀원'),50)) on conflict do nothing;return pid;end$$;
revoke all on function tm_private.create_project(text,text,date,text),tm_private.join_project(text,text) from public;
grant execute on function tm_private.create_project(text,text,date,text),tm_private.join_project(text,text) to authenticated;
create function public.tm_create(project_name text,course_name text,due_date date,display_name text) returns uuid language sql security invoker set search_path='' as $$select tm_private.create_project(project_name,course_name,due_date,display_name)$$;
create function public.tm_join(code text,display_name text) returns uuid language sql security invoker set search_path='' as $$select tm_private.join_project(code,display_name)$$;
revoke all on function public.tm_create(text,text,date,text),public.tm_join(text,text) from public,anon;
grant execute on function public.tm_create(text,text,date,text),public.tm_join(text,text) to authenticated;
revoke all on public.tm_projects,public.tm_members,public.tm_items from anon,authenticated;
grant select on public.tm_projects,public.tm_members,public.tm_items to authenticated;
grant update(role) on public.tm_members to authenticated;
grant insert,update on public.tm_items to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('team-files','team-files',false,10485760,array['application/pdf','image/png','image/jpeg','image/webp','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','text/plain','application/octet-stream']);
create policy team_file_read on storage.objects for select to authenticated using(bucket_id='team-files' and tm_private.is_member((storage.foldername(name))[1]::uuid));
create policy team_file_insert on storage.objects for insert to authenticated with check(bucket_id='team-files' and tm_private.is_member((storage.foldername(name))[1]::uuid));
commit;
